import dayjs from "dayjs";
const isValidOffset = (numberString, unit) => {
    if (!(numberString && unit)) {
        return false;
    }
    if (unit.length < 3) {
        return false;
    }
    const duration = dayjs
        .duration(1, unit)
        .valueOf();
    if (duration > 0) {
        const number = Number(numberString.trim());
        return Number.isInteger(number) && number > 0;
    }
    return false;
};
/**
 * Parse a preset time frame string value, returning its millisecond representation relative to the given date
 * @param {string} timeFrame string date offset
 * @param {Dayjs} referenceDate to calculate the offset from
 */
export const parseTimeFrame = (timeFrame, referenceDate) => {
    const normalisedTimeFrame = timeFrame.trim().toLowerCase();
    if (normalisedTimeFrame === "today") {
        return {
            from: dayjs.utc(referenceDate).startOf("day").valueOf(),
            timeFrame,
            to: referenceDate.valueOf(),
        };
    }
    if (normalisedTimeFrame === "yesterday") {
        return {
            from: referenceDate.startOf("day").subtract(1, "day").valueOf(),
            timeFrame,
            to: referenceDate.startOf("day").subtract(1, "second").valueOf(),
        };
    }
    if (normalisedTimeFrame === "last full month") {
        return {
            from: referenceDate.subtract(1, "month").startOf("month").valueOf(),
            timeFrame,
            to: referenceDate.subtract(1, "month").endOf("month").valueOf(),
        };
    }
    const [offsetDirection, number, unit] = normalisedTimeFrame.split(" ");
    if (isValidOffset(number, unit)) {
        switch (offsetDirection.trim().toLowerCase()) {
            case "last":
                return {
                    from: referenceDate
                        .subtract(parseInt(number, 10), unit.toLowerCase())
                        .valueOf(),
                    timeFrame,
                    to: referenceDate.valueOf(),
                };
            case "next":
                return {
                    from: referenceDate
                        .add(parseInt(number, 10), unit.toLowerCase())
                        .valueOf(),
                    timeFrame,
                    to: referenceDate.valueOf(),
                };
            default:
                return undefined;
        }
    }
    return undefined;
};
